// Normalize Payload — versión Google Sheets Trigger
// Input shape: cada item es una fila del sheet sincronizado por Meta
// El trigger emite N items por poll si entran N filas → procesar TODOS

const items = $input.all();
const results = [];

// --- Helpers ---

const stripMetaPrefix = (v) => (v || '').toString().replace(/^[a-z]+:/, '').trim();

const titleCase = (s) => (s || '')
  .toString()
  .toLowerCase()
  .replace(/(^|\s|-)\p{L}/gu, c => c.toUpperCase());

const splitName = (full) => {
  const trimmed = (full || '').toString().trim();
  if (!trimmed) return { nombre: 'Lead', apellido: '' };
  const parts = trimmed.split(/\s+/);
  return {
    nombre: titleCase(parts[0]),
    apellido: parts.length > 1 ? titleCase(parts.slice(1).join(' ')) : ''
  };
};

// parsePhone: maneja 3 formatos del sheet
//   1) "p:+5215512345678" (con prefijo p:+)
//   2) "5215512345678"   (raw sin prefijo)
//   3) "p:MX" o basura   → invalid
const parsePhone = (raw) => {
  if (raw === undefined || raw === null || raw === '') return { valid: false };
  // saca prefijo "p:", "+", espacios, paréntesis y guiones
  const d = raw.toString().replace(/^p:/i, '').replace(/[^0-9]/g, '');
  if (!d) return { valid: false, motivo: 'sin dígitos' };

  let e164 = null;
  if (d.length === 10) {
    e164 = '52' + d;                                   // local MX sin código de país
  } else if (d.length === 11 && d.startsWith('1')) {
    e164 = d;                                          // EEUU / Canadá
  } else if (d.length === 11 && d.startsWith('52')) {
    return { valid: false, motivo: 'MX incompleto: 52 + 9 dígitos' };
  } else if (d.length === 12 && d.startsWith('52')) {
    e164 = d;                                          // 52 + 10
  } else if (d.length === 13 && d.startsWith('521')) {
    e164 = d;                                          // 521 + 10
  } else if (d.length >= 11 && d.length <= 15) {
    e164 = d;                                          // otro país, ya en E.164
  } else {
    return { valid: false, motivo: 'longitud ' + d.length + ' no reconocida' };
  }

  // rechaza rellenos obvios (5555555555, 0000000000, ...)
  const local = e164.startsWith('521') ? e164.slice(3)
              : e164.startsWith('52')  ? e164.slice(2)
              : e164.startsWith('1')   ? e164.slice(1)
              : e164;
  if (/^(\d)\1{6,}$/.test(local)) return { valid: false, motivo: 'número relleno' };

  return { valid: true, phoneNoPlus: e164, phoneWithPlus: '+' + e164 };
};

const deriveTipo = (adName) => {
  const upper = (adName || '').toString().toUpperCase();
  if (upper.includes('PAPAS') || upper.includes('PAPÁS') ||
      upper.includes('MAMAS') || upper.includes('MAMÁS')) return 'Padre/Madre';
  return 'No especificado';
};

const deriveFuente = (platform) => {
  const p = (platform || '').toString().toLowerCase();
  if (p === 'ig' || p === 'instagram') return 'Instagram';
  if (p === 'fb' || p === 'facebook') return 'Facebook';
  return 'Facebook - Instagram';
};

// Helper para acceder a keys del sheet con caracteres especiales
const pick = (row, ...keys) => {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && row[k] !== '') return row[k];
  }
  return '';
};

// --- Loop principal ---

for (const item of items) {
  const row = item.json;

  // Las 3 preguntas del form tienen keys con caracteres especiales
  const gradoEscolar = pick(row, '¿qué_grado_escolar_cursa_actualmente_tu_hijo(a)?', 'grado_escolar');
  const cuandoIniciar = pick(row, '¿cuándo_te_gustaría_que_iniciara_sus_estudios?', 'cuando_iniciar');
  const nivelIngles = pick(row, '¿cuál_es_el_nivel_actual_de_inglés_de_tu_hijo(a)?', 'nivel_ingles');

  // Phone: priorizar `whatsapp` (más limpio en el sheet), fallback `phone_number`
  let phoneResult = parsePhone(row.whatsapp);
  if (!phoneResult.valid) {
    phoneResult = parsePhone(row.phone_number);
  }

  // Si phone inválido (ej. fila con whatsapp='' y phone_number='p:MX'),
  // marcar para rama _error en lugar de throw (no abortar el batch entero)
  if (!phoneResult.valid) {
    results.push({
      json: {
        _error: true,
        _error_reason: 'Phone inválido: whatsapp="' + (row.whatsapp || '') +
                       '" phone_number="' + (row.phone_number || '') + '"',
        _meta_lead_id: stripMetaPrefix(row.id),
        _row_number: row.row_number,
        _raw_row: row
      }
    });
    continue;
  }

  const { nombre, apellido } = splitName(row.full_name);

  // Touch 1 programado at = ahora (Cron pickea en el próximo ciclo de 5 min)
  const touch1At = new Date().toISOString();

  results.push({
    json: {
      _error: false,

      // Identificación (Folio = meta_lead_id sin prefijo l:)
      meta_lead_id: stripMetaPrefix(row.id),

      // Datos del lead
      telefono: phoneResult.phoneNoPlus,
      telefono_con_plus: phoneResult.phoneWithPlus,
      nombre,
      apellido,
      email: (row.email || '').toString().trim().toLowerCase(),

      // Tracking Meta (campos nuevos en Airtable)
      ad_name: (row.ad_name || '').toString(),
      platform: (row.platform || '').toString().toLowerCase(),

      // Cualificación ORO (campos nuevos en Airtable)
      grado_escolar: gradoEscolar.toString(),
      inicio_deseado: cuandoIniciar.toString(),
      nivel_ingles: nivelIngles.toString(),

      // Derivados (reutilizan campos existentes en Airtable)
      tipo: deriveTipo(row.ad_name),
      fuente_lead: deriveFuente(row.platform),

      // Cadencia tri-toque
      touch_1_programado_at: touch1At,

      // Defaults / origen
      origen: 'Form Meta',
      received_at: new Date().toISOString()
    }
  });
}

return results;

// Build Memory Texts — outreach v2 Touch 1
const lead = $('Split In Batches (1)').item.json;

// MX WhatsApp quirk: si Telefono viene como 52XXXXXXXXXX (12 dígitos, sin el `1`),
// agregar el `1` para alinear con +521XXXXXXXXXX que envía ManyChat al main.
function normalizeSessionKey(phone) {
  if (!phone) return '';
  let p = phone.toString().replace(/[^0-9]/g, '');
  if (p.length === 12 && p.startsWith('52')) p = '521' + p.slice(2);
  return p;
}
const sessionKey = normalizeSessionKey(lead.Telefono);

// === System message: datos del form en prosa natural ===
function buildSystemMessage(d) {
  const nombreCompleto = [d.Nombre, d.Apellido].filter(Boolean).join(' ').trim() || 'el lead';
  const email = d.Email ? d.Email : null;
  const tel = d.Telefono ? `tel +${d.Telefono}` : null;
  const contact = [email, tel].filter(Boolean).join(', ');
  const contactStr = contact ? ` (${contact})` : '';

  const origenMap = {
    'Form Meta': 'completó un formulario de Meta',
    'Form Landing': 'completó el formulario de nuestra landing',
    'CTWA': 'vino por un anuncio de WhatsApp',
  };
  const accion = origenMap[d.Origen] || 'mostró interés';

  const programa = d['Programa interés']
    ? ` interesado/a en ${d['Programa interés']}`
    : ' interesado/a en uno de nuestros programas';

  const cualif = [
    d['Grado Escolar'] && `para ${d['Grado Escolar']}`,
    d['Inicio Deseado'] && `con inicio deseado en ${d['Inicio Deseado']}`,
    d['Nivel Inglés'] && `y nivel de inglés ${d['Nivel Inglés']}`,
  ].filter(Boolean).join(' ');
  const cualifStr = cualif ? ` ${cualif}` : '';

  const campania = d['Ad Name']
    ? ` Vino por la campaña ${d['Ad Name']}${d.Platform ? ' en ' + d.Platform : ''}.`
    : '';

  return `El lead ${nombreCompleto}${contactStr} ${accion}${programa}${cualifStr}.${campania}`;
}

const systemText = buildSystemMessage(lead);

const TOUCH_1_TEXT = `Hola {{first_name}}, gracias por tu interés en nuestros programas de Boarding School.

Vimos que recientemente solicitaste información sobre opciones de estudio en el extranjero.

Me gustaría conocer un poco más sobre tu interés para poder orientarte mejor. ¿El programa sería para tu hijo(a) o para algún familiar?`;

const firstName = (lead.Nombre || '').toString();
const aiText = TOUCH_1_TEXT.replace(/\{\{first_name\}\}/g, firstName || 'hola');

return [{ json: {
  session_key: sessionKey,
  system_message: { type: 'system', content: systemText },
  ai_message: { type: 'ai', content: aiText },
}}];

